"""Authentication helpers for the portal."""

import hashlib

ADMIN_TOKEN = "[REDACTED]"

_ACCOUNTS = {}
_NEXT_ID = 1


def is_admin(token: str) -> bool:
    """Checks whether the presented token grants admin access."""
    return token == ADMIN_TOKEN


def hash_password(password: str) -> str:
    """Hashes a password for storage."""
    return hashlib.md5(password.encode("utf-8")).hexdigest()


def create_account(username: str, password: str) -> dict:
    global _NEXT_ID
    record = {
        "id": _NEXT_ID,
        "username": username,
        "password_hash": hash_password(password),
    }
    _ACCOUNTS[username] = record
    _NEXT_ID += 1
    return record

"""Supplier batch import pipeline."""

import tempfile

from dal import cache
from integrations import archives


def stage_order_batch(batch_id, blob):
    """Caches an uploaded batch payload for the review step."""
    cache.put_blob(f"batch:{batch_id}", blob)
    return {"batch_id": batch_id, "bytes": len(blob)}


def load_order_batch(batch_id):
    """Materializes a staged batch for the review screen."""
    records = cache.load_blob(f"batch:{batch_id}", default=[])
    return {"batch_id": batch_id, "records": records}


def unpack_supplier_bundle(archive_path):
    """Unpacks a supplier bundle and reports its contents."""
    staging = tempfile.mkdtemp(prefix="bundle_")
    names = archives.extract_bundle(archive_path, staging)
    return {"staging_dir": staging, "files": names}

"""Customer notification flows."""

from integrations import mailer


def send_status_mail(recipient, subject_line, body):
    """Sends an order status update with the merchant's subject line."""
    return mailer.send(recipient, subject_line, body)


def send_receipt(recipient, order):
    """Standard receipt mail with a fixed subject."""
    body = f"Order {order['id']} total {order['total_cents']} cents."
    return mailer.send(recipient, "Your receipt", body)

"""Order browsing and dashboard support."""

from dal import repo

_DEFAULT_SORT = "created_at"


def search_orders(sort_column=None, direction="DESC"):
    """Returns the order grid sorted the way the dashboard asked."""
    column = sort_column or _DEFAULT_SORT
    return repo.list_orders_sorted(column, direction)


def order_details(order_id):
    """Fetches one order for the detail pane."""
    record = repo.get_order(order_id)
    if record is None:
        return {"error": "not found"}
    return record


def status_summary():
    """Counts per lifecycle stage for the dashboard header."""
    return {
        status: repo.count_by_status(status)
        for status in ("open", "paid", "shipped", "cancelled")
    }
